import { API_BASE_URL } from '../utils/appEnv';

/**
 * agentCompanySettingApi — one company's settings for each catalog agent
 * (dbo.agentCompanySettings). Generated by posgmo-factory (PRD
 * prd_agentCompanySetting.json) and fixed by hand.
 *   POST /all_agentCompanySettings  — staff of that company
 *   POST /agentCompanySettings      — upsert; admin/manager of that company
 * extraInstructions are behavior notes only (tone, topics to avoid, who to hand
 * off to); business data lives in Agente WhatsApp › Configurar.
 * The backend stamps updatedByUserId from the session token.
 */
const LOG = '[agentCompanySettingApi]';

export const DISPLAY_NAME_MAX = 80;
export const EXTRA_INSTRUCTIONS_MAX = 1000;

export interface AgentCompanySetting {
  agentCompanySettingId: number;
  companyId: number;
  agentId: number;
  agentKey: string;
  agentName: string;
  displayName: string;
  extraInstructions: string;
  updatedAt: string;
}

export interface AgentCompanySettingInput {
  companyId: number;
  agentId: number;
  displayName: string;
  extraInstructions: string;
}

interface Row extends Omit<AgentCompanySetting, 'updatedAt'> { updated_at?: string }

async function post<T>(path: string, body: unknown): Promise<T> {
  const res = await fetch(`${API_BASE_URL}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || data?.error || data?.status === 'error') {
    const message = data?.message || data?.error || data?.detail || `HTTP ${res.status}`;
    console.error(LOG, path, message);
    throw new Error(typeof message === 'string' ? message : 'Error');
  }
  return data as T;
}

export async function getAllAgentCompanySettings(companyId: number): Promise<AgentCompanySetting[]> {
  const data = await post<{ agentCompanySettings?: Row[] }>(
    '/all_agentCompanySettings', { agentCompanySettings: [{ companyId }] });
  return (data.agentCompanySettings ?? []).map(({ updated_at, ...r }) => ({ ...r, updatedAt: updated_at ?? '' }));
}

/** Upsert by (companyId, agentId); empty strings are stored as NULL (= agent default). */
export async function saveAgentCompanySetting(input: AgentCompanySettingInput): Promise<void> {
  await post('/agentCompanySettings', { agentCompanySettings: [input] });
}
